#!/usr/bin/env bash

# Wrapper script that is to be configured as htcondor's main executable file

htcondor_wrapper() {
    # helper to select the correct python executable
    _law_python() {
        command -v python &> /dev/null && python "$@" || python3 "$@"
    }

    #
    # detect variables
    #

    local shell_is_zsh="$( [ -z "${ZSH_VERSION}" ] && echo "false" || echo "true" )"
    local this_file="$( ${shell_is_zsh} && echo "${(%):-%x}" || echo "${BASH_SOURCE[0]}" )"
    local this_file_base="$( basename "${this_file}" )"

    # get the job number
    export LAW_HTCONDOR_JOB_NUMBER="${LAW_HTCONDOR_JOB_PROCESS}"
    if [ -z "${LAW_HTCONDOR_JOB_NUMBER}" ]; then
        >&2 echo "could not determine htcondor job number"
        return "1"
    fi
    # htcondor process numbers start at 0, law job numbers at 1, so increment
    ((LAW_HTCONDOR_JOB_NUMBER++))
    echo "running ${this_file_base} for job number ${LAW_HTCONDOR_JOB_NUMBER}"


    #
    # job argument definitons, depending on LAW_HTCONDOR_JOB_NUMBER
    #

    # definition
    local htcondor_job_arguments_map
    declare -A htcondor_job_arguments_map
    htcondor_job_arguments_map=(
        ['1']="columnflow.tasks.reduction ReduceEvents  MTA= 1 no LQ=="
        ['2']="columnflow.tasks.reduction ReduceEvents  MTE= 1 no LQ=="
        ['3']="columnflow.tasks.reduction ReduceEvents  MTI= 1 no LQ=="
        ['4']="columnflow.tasks.reduction ReduceEvents  MTM= 1 no LQ=="
        ['5']="columnflow.tasks.reduction ReduceEvents  MTQ= 1 no LQ=="
        ['6']="columnflow.tasks.reduction ReduceEvents  MTU= 1 no LQ=="
        ['7']="columnflow.tasks.reduction ReduceEvents  MTY= 1 no LQ=="
        ['8']="columnflow.tasks.reduction ReduceEvents  MTc= 1 no LQ=="
        ['9']="columnflow.tasks.reduction ReduceEvents  MTg= 1 no LQ=="
        ['10']="columnflow.tasks.reduction ReduceEvents  MTk= 1 no LQ=="
        ['11']="columnflow.tasks.reduction ReduceEvents  MjA= 1 no LQ=="
        ['12']="columnflow.tasks.reduction ReduceEvents  MjE= 1 no LQ=="
        ['13']="columnflow.tasks.reduction ReduceEvents  MjI= 1 no LQ=="
        ['14']="columnflow.tasks.reduction ReduceEvents  MjM= 1 no LQ=="
        ['15']="columnflow.tasks.reduction ReduceEvents  MjQ= 1 no LQ=="
        ['16']="columnflow.tasks.reduction ReduceEvents  MjU= 1 no LQ=="
        ['17']="columnflow.tasks.reduction ReduceEvents  MjY= 1 no LQ=="
        ['18']="columnflow.tasks.reduction ReduceEvents  Mjc= 1 no LQ=="
        ['19']="columnflow.tasks.reduction ReduceEvents  Mjg= 1 no LQ=="
        ['20']="columnflow.tasks.reduction ReduceEvents  Mjk= 1 no LQ=="
        ['21']="columnflow.tasks.reduction ReduceEvents  MzA= 1 no LQ=="
        ['22']="columnflow.tasks.reduction ReduceEvents  MzE= 1 no LQ=="
        ['23']="columnflow.tasks.reduction ReduceEvents  MzI= 1 no LQ=="
        ['24']="columnflow.tasks.reduction ReduceEvents  MzM= 1 no LQ=="
        ['25']="columnflow.tasks.reduction ReduceEvents  MzQ= 1 no LQ=="
        ['26']="columnflow.tasks.reduction ReduceEvents  MzU= 1 no LQ=="
        ['27']="columnflow.tasks.reduction ReduceEvents  MzY= 1 no LQ=="
        ['28']="columnflow.tasks.reduction ReduceEvents  Mzc= 1 no LQ=="
        ['29']="columnflow.tasks.reduction ReduceEvents  Mzg= 1 no LQ=="
        ['30']="columnflow.tasks.reduction ReduceEvents  Mzk= 1 no LQ=="
        ['31']="columnflow.tasks.reduction ReduceEvents  NDA= 1 no LQ=="
        ['32']="columnflow.tasks.reduction ReduceEvents  NDE= 1 no LQ=="
        ['33']="columnflow.tasks.reduction ReduceEvents  NDI= 1 no LQ=="
        ['34']="columnflow.tasks.reduction ReduceEvents  NDM= 1 no LQ=="
        ['35']="columnflow.tasks.reduction ReduceEvents  NDQ= 1 no LQ=="
        ['36']="columnflow.tasks.reduction ReduceEvents  NDU= 1 no LQ=="
        ['37']="columnflow.tasks.reduction ReduceEvents  NDY= 1 no LQ=="
        ['38']="columnflow.tasks.reduction ReduceEvents  NDc= 1 no LQ=="
        ['39']="columnflow.tasks.reduction ReduceEvents  NDg= 1 no LQ=="
        ['40']="columnflow.tasks.reduction ReduceEvents  NDk= 1 no LQ=="
        ['41']="columnflow.tasks.reduction ReduceEvents  NTA= 1 no LQ=="
        ['42']="columnflow.tasks.reduction ReduceEvents  NTE= 1 no LQ=="
        ['43']="columnflow.tasks.reduction ReduceEvents  NTI= 1 no LQ=="
        ['44']="columnflow.tasks.reduction ReduceEvents  NTM= 1 no LQ=="
        ['45']="columnflow.tasks.reduction ReduceEvents  NTQ= 1 no LQ=="
        ['46']="columnflow.tasks.reduction ReduceEvents  NTU= 1 no LQ=="
        ['47']="columnflow.tasks.reduction ReduceEvents  NTY= 1 no LQ=="
        ['48']="columnflow.tasks.reduction ReduceEvents  NTc= 1 no LQ=="
        ['49']="columnflow.tasks.reduction ReduceEvents  NTg= 1 no LQ=="
        ['50']="columnflow.tasks.reduction ReduceEvents  NTk= 1 no LQ=="
        ['51']="columnflow.tasks.reduction ReduceEvents  NjA= 1 no LQ=="
        ['52']="columnflow.tasks.reduction ReduceEvents  NjE= 1 no LQ=="
        ['53']="columnflow.tasks.reduction ReduceEvents  NjI= 1 no LQ=="
        ['54']="columnflow.tasks.reduction ReduceEvents  NjM= 1 no LQ=="
        ['55']="columnflow.tasks.reduction ReduceEvents  NjQ= 1 no LQ=="
        ['56']="columnflow.tasks.reduction ReduceEvents  NjU= 1 no LQ=="
        ['57']="columnflow.tasks.reduction ReduceEvents  NjY= 1 no LQ=="
        ['58']="columnflow.tasks.reduction ReduceEvents  Njc= 1 no LQ=="
        ['59']="columnflow.tasks.reduction ReduceEvents  Njg= 1 no LQ=="
        ['60']="columnflow.tasks.reduction ReduceEvents  Njk= 1 no LQ=="
        ['61']="columnflow.tasks.reduction ReduceEvents  NzA= 1 no LQ=="
    )

    # pick
    local htcondor_job_arguments="${htcondor_job_arguments_map[${LAW_HTCONDOR_JOB_NUMBER}]}"
    if [ -z "${htcondor_job_arguments}" ]; then
        >&2 echo "empty htcondor job arguments for LAW_HTCONDOR_JOB_NUMBER ${LAW_HTCONDOR_JOB_NUMBER}"
        return "3"
    fi


    #
    # variable rendering
    #

    # check variables
    local render_variables=""
    if [ -z "${render_variables}" ]; then
        >&2 echo "empty render variables"
        return "4"
    fi

    # decode
    render_variables="$( echo "${render_variables}" | base64 --decode )"

    # check files to render
    local input_files_render=( law_job_d08599bc08.sh remote_bootstrap_d07e50ba95.sh )
    if [ "${#input_files_render[@]}" == "0" ]; then
        >&2 echo "received empty input files for rendering for LAW_HTCONDOR_JOB_NUMBER ${LAW_HTCONDOR_JOB_NUMBER}"
        return "5"
    fi

    # render files
    local input_file_render
    for input_file_render in ${input_files_render[@]}; do
        # skip if the file refers to _this_ one
        local input_file_render_base="$( basename "${input_file_render}" )"
        [ "${input_file_render_base}" = "${this_file_base}" ] && continue
        # render
        echo "render ${input_file_render}"
        cat > _render.py << EOT
import re
repl = ${render_variables}
repl['input_files_render'] = ''
repl['file_postfix'] = '${file_postfix}' or repl.get('file_postfix', '')
repl['log_file'] = ''
content = open('${input_file_render}', 'r').read()
content = re.sub(r'\{\{(\w+)\}\}', lambda m: repl.get(m.group(1), ''), content)
open('${input_file_render_base}', 'w').write(content)
EOT
        _law_python _render.py
        local render_ret="$?"
        rm -f _render.py
        # handle rendering errors
        if [ "${render_ret}" != "0" ]; then
            >&2 echo "input file rendering failed with code ${render_ret}"
            return "6"
        fi
    done


    #
    # run the actual job file
    #

    # check the job file
    local job_file="law_job_d08599bc08.sh"
    if [ ! -f "${job_file}" ]; then
        >&2 echo "job file '${job_file}' does not exist"
        return "7"
    fi

    # helper to print a banner
    banner() {
        local msg="$1"

        echo
        echo "================================================================================"
        echo "=== ${msg}"
        echo "================================================================================"
        echo
    }

    # debugging: print its contents
    # echo "=== content of job file '${job_file}'"
    # echo
    # cat "${job_file}"
    # echo
    # echo "=== end of job file content"

    # run it
    banner "Start of law job"

    local job_ret
    bash "${job_file}" ${htcondor_job_arguments}
    job_ret="$?"

    banner "End of law job"

    return "${job_ret}"
}

action() {
    # arguments: file_postfix, log_file
    local file_postfix="$1"
    local log_file="$2"

    # create log directory
    if [ ! -z "${log_file}" ]; then
        local log_dir="$( dirname "${log_file}" )"
        [ ! -d "${log_dir}" ] && mkdir -p "${log_dir}"
    fi

    # run the wrapper function
    if [ -z "${log_file}" ]; then
        htcondor_wrapper "$@"
    elif command -v tee &> /dev/null; then
        set -o pipefail
        echo "---" >> "${log_file}"
        htcondor_wrapper "$@" 2>&1 | tee -a "${log_file}"
    else
        echo "---" >> "${log_file}"
        htcondor_wrapper "$@" &>> "${log_file}"
    fi
}

action "$@"
